'use strict';
const http=require('node:http');
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const {URL}=require('node:url');
const {DatabaseSync}=require('node:sqlite');
const {createMailService,validEmail}=require('./mail-service');
const {createShopFeatures}=require('./shop-features');
let shopFeatures;
let mailService;

loadEnv(path.join(__dirname,'.env'));
const PORT=Number(process.env.PORT||3000);
const ADMIN_PASSWORD=process.env.ADMIN_PASSWORD;
if(!ADMIN_PASSWORD||ADMIN_PASSWORD==='change-this-to-a-long-private-password'){console.error('ADMIN_PASSWORD must be set in a private .env file. See .env.example.');process.exit(1);}

const DATA_DIR=path.join(__dirname,'data');
const UPLOADS_DIR=path.join(__dirname,'uploads');
fs.mkdirSync(DATA_DIR,{recursive:true});fs.mkdirSync(UPLOADS_DIR,{recursive:true});
const db=new DatabaseSync(path.join(DATA_DIR,'shop.sqlite'));
db.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;');
const sessions=new Map();
const STATUSES=['new','confirmed','processing','shipped','delivered','cancelled'];
const STATUS_LABELS={new:'Yeni',confirmed:'Təsdiqləndi',processing:'Hazırlanır',shipped:'Göndərildi',delivered:'Çatdırıldı',cancelled:'Ləğv edildi'};
const NOTIFIABLE=new Set(['confirmed','shipped','delivered','cancelled']);
const SIZE_PRESETS={tops:['S','M','L','XL'],shirts:['M','L','XL'],pants:['28','30','32','34','36'],one:['Standart']};

setupDatabase();

const server=http.createServer(async(req,res)=>{
  try{
    const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),route=url.pathname;
    if(req.method==='GET'&&route==='/')return customerPage(res,url);
    if(req.method==='GET'&&/^\/product\/\d+$/.test(route))return productDetail(res,route);
    if(req.method==='GET'&&route==='/checkout')return checkoutPage(res);
    if(req.method==='POST'&&route==='/checkout')return await checkout(req,res);
    if(req.method==='POST'&&route==='/orders')return await checkout(req,res);
    if(req.method==='GET'&&route==='/thank-you')return thankYou(res,url);
    if(req.method==='POST'&&route==='/api/cart')return await shopFeatures.cartQuote(req,res);
    const newAssets={'/shop-ui.js':'application/javascript; charset=utf-8','/admin-live.js':'application/javascript; charset=utf-8','/product-editor.js':'application/javascript; charset=utf-8','/premium.css':'text/css; charset=utf-8'};
    if(req.method==='GET'&&newAssets[route])return serveFile(res,path.join(__dirname,'public',route.slice(1)),newAssets[route]);
    if(req.method==='GET'&&route==='/health')return sendText(res,200,'ok');
    if(req.method==='GET'&&route==='/styles.css')return serveFile(res,path.join(__dirname,'public','styles.css'),'text/css; charset=utf-8');
    if(req.method==='GET'&&route==='/auren-fashion-banner.png')return serveFile(res,path.join(__dirname,'public','auren-fashion-banner.png'),'image/png');
    if(req.method==='GET'&&route==='/product-tools.js')return serveFile(res,path.join(__dirname,'public','product-tools.js'),'application/javascript; charset=utf-8');
    if(req.method==='GET'&&route==='/store.css')return serveFile(res,path.join(__dirname,'public','store.css'),'text/css; charset=utf-8');
    if(req.method==='GET'&&route.startsWith('/uploads/'))return serveUpload(res,route);
    if(req.method==='GET'&&route==='/admin/login')return loginPage(res,url);
    if(req.method==='POST'&&route==='/admin/login')return await login(req,res);
    const session=requireAdmin(req,res);if(!session)return;
    if(req.method==='POST'&&route==='/admin/logout')return await logout(req,res,session);
    if(req.method==='GET'&&route==='/admin/events')return shopFeatures.subscribe(req,res,session);
    if(req.method==='GET'&&route==='/admin/orders-fragment')return shopFeatures.orderFragment(res,url,session);
    if(req.method==='POST'&&route==='/admin/categories')return await shopFeatures.saveCategory(req,res,session);
    if(req.method==='GET'&&route==='/admin')return adminOrders(res,url,session);
    if(req.method==='POST'&&/^\/admin\/orders\/\d+\/status$/.test(route))return await changeStatus(req,res,route,session);
    if(req.method==='POST'&&/^\/admin\/products\/\d+\/images\/\d+\/primary$/.test(route))return await setPrimaryProductImage(req,res,route,session);
    if(req.method==='GET'&&route==='/admin/products')return productsPage(res,url,session);
    if(req.method==='POST'&&/^\/admin\/products\/\d+\/images\/\d+\/delete$/.test(route))return await deleteProductImage(req,res,route,session);
    if(req.method==='POST'&&route==='/admin/products')return await saveProduct(req,res,session,url);
    if(req.method==='POST'&&/^\/admin\/products\/\d+\/toggle$/.test(route))return await toggleProduct(req,res,route,session);
    if(req.method==='POST'&&/^\/admin\/products\/\d+\/delete$/.test(route))return await deleteProduct(req,res,route,session);
    if(req.method==='POST'&&route==='/admin/notifications/retry'){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);mailService.retryFailed();return redirect(res,'/admin/settings?retried=1');}
    if(req.method==='GET'&&route==='/admin/settings')return settingsPage(res,url,session);
    if(req.method==='POST'&&route==='/admin/settings')return await saveSettings(req,res,session);
    if(req.method==='GET'&&route==='/admin/export.xls')return redirect(res,'/admin/export.xlsx');
    if(req.method==='GET'&&route==='/admin/export.xlsx')return await exportOrders(res);
    return notFound(res);
  }catch(error){console.error(error);return sendHtml(res,500,errorPage('Gözlənilməyən xəta','Zəhmət olmasa yenidən cəhd edin.'));}
});
server.listen(PORT,()=>console.log(`Order manager is running at http://localhost:${PORT}`));

function setupDatabase(){
  db.exec(`
    CREATE TABLE IF NOT EXISTS products (
      id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',
      sizes TEXT NOT NULL DEFAULT '[]',image_url TEXT NOT NULL DEFAULT '',price_azn REAL NOT NULL CHECK(price_azn>=0),
      is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS orders (
      id INTEGER PRIMARY KEY AUTOINCREMENT,customer_name TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'new',total_azn REAL NOT NULL,exchange_rate REAL NOT NULL,total_usd REAL NOT NULL,
      created_at TEXT NOT NULL,updated_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS order_items (
      id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER,
      product_name TEXT NOT NULL,unit_price_azn REAL NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),
      selected_size TEXT NOT NULL DEFAULT '',line_total_azn REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS order_status_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),old_status TEXT,
      new_status TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id),status TEXT NOT NULL,
      channel TEXT NOT NULL,state TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS orders_customer_name ON orders(customer_name);
    CREATE INDEX IF NOT EXISTS orders_phone ON orders(phone);
    CREATE INDEX IF NOT EXISTS orders_status ON orders(status);
  `);
  addColumnIfMissing('products','sizes',"sizes TEXT NOT NULL DEFAULT '[]'");
  addColumnIfMissing('products','image_url',"image_url TEXT NOT NULL DEFAULT ''");
  addColumnIfMissing('order_items','selected_size',"selected_size TEXT NOT NULL DEFAULT ''");
  if(!db.prepare("SELECT 1 FROM settings WHERE key='exchange_rate'").get())db.prepare('INSERT INTO settings(key,value,updated_at)VALUES(?,?,?)').run('exchange_rate','1.70',now());
  db.prepare("UPDATE products SET sizes='[\"Standart\"]' WHERE sizes IS NULL OR sizes='' OR sizes='[]'").run();
  const products=[
    ['Oversize Basic Tişört – Siyah','tops'],['Oversize Basic Tişört – Beyaz','tops'],['Basic Polo Yaka Tişört – Lacivert','tops'],['Relaxed Fit Gömlek – Bej','shirts'],['Oversize Gömlek – Beyaz','tops'],['Denim Gömlek – Açık Mavi','shirts'],['Basic Hoodie – Gri','tops'],['Oversize Hoodie – Siyah','shirts'],['Fermuarlı Sweatshirt – Antrasit','tops'],['Basic Sweatshirt – Krem','tops'],['Cargo Pantolon – Siyah','pants'],['Baggy Jean – Açıq Mavi','pants'],['Straight Jean – Lacivert','pants'],['Wide Leg Pantolon – Bej','tops'],['Jogger Pantolon – Gri','tops'],['Bomber Ceket – Siyah','tops'],['Denim Ceket – Mavi','tops'],['Triko Kazak – Krem','tops'],['Basic Hırka – Kahverengi','tops'],['Oversize Blazer – Siyah','tops']
  ];
  const exists=db.prepare('SELECT 1 FROM products WHERE name=?');
  const insert=db.prepare('INSERT INTO products(name,description,sizes,image_url,price_azn,is_active,created_at,updated_at)VALUES(?,?,?,?,?,?,?,?)');
  const t=now();
  for(const [name,preset] of products)if(!exists.get(name))insert.run(name,'Qiymət və şəkil admin tərəfindən tamamlanmalıdır.',JSON.stringify(SIZE_PRESETS[preset]),'',0,0,t,t);
}
function addColumnIfMissing(table,column,definition){if(!db.prepare(`PRAGMA table_info(${table})`).all().some(row=>row.name===column))db.exec(`ALTER TABLE ${table} ADD COLUMN ${definition}`);}

function customerPage(res){
  const products=db.prepare('SELECT id,name,description,sizes,image_url,price_azn FROM products WHERE is_active=1 AND price_azn>0 ORDER BY name').all().map(product=>({...product,sizes:parseSizes(product.sizes)}));
  if(!products.length)return sendHtml(res,200,page('Məhsullar','<main class="container"><section class="empty-state"><span>✦</span><h1>Yeni kolleksiya hazırlanır</h1><p>Məhsullar tezliklə sifarişə açılacaq.</p></section></main>'));
  const rate=exchangeRate();
  const catalog=products.map(p=>`<article class="catalog-card">${imageMarkup(p.image_url,p.name)}<div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.sizes.join(' · '))}</p><strong>${money(p.price_azn)} AZN <small>$${money(p.price_azn/rate)}</small></strong></div></article>`).join('');
  const productData=JSON.stringify(products).replace(/</g,'\\u003c');
  const content=`<main class="container customer-page">
    <section class="hero"><p class="eyebrow">ONLINE MAĞAZA</p><h1>Sevdiyin stili bir neçə addımda seç.</h1><p>Hesab yaratmadan, telefondan rahat sifariş ver.</p></section>
    <section class="catalog"><div class="section-title"><h2>Kolleksiya</h2><span>${products.length} məhsul</span></div><div class="catalog-grid">${catalog}</div></section>
    <form class="card order-form" method="post" action="/orders" id="order-form"><div class="section-title"><h2>Sifarişin</h2><span>1–99 ədəd</span></div><div id="item-rows"></div><button class="button secondary add-item" type="button" id="add-item">＋ Məhsul əlavə et</button><div class="totals"><span>Cəmi məbləğ</span><strong id="total-azn">0.00 AZN</strong><small id="total-usd">$0.00 USD</small></div><h2>Çatdırılma məlumatları</h2><label>Ad və soyad<input name="customer_name" required maxlength="100" autocomplete="name"></label><label>Telefon nömrəsi<input name="phone" required maxlength="30" inputmode="tel" autocomplete="tel" placeholder="050 123 45 67"></label><label>Ünvan<textarea name="address" required maxlength="500" autocomplete="street-address" rows="3" placeholder="Şəhər, küçə, bina/mənzil"></textarea></label><input type="hidden" name="items" id="items-input"><button class="button primary submit" type="submit">Sifarişi təsdiqlə →</button><p class="fine-print">USD məbləği 1 USD = ${money(rate)} AZN məzənnəsi ilə hesablanır.</p></form>
  </main><script>const PRODUCTS=${productData},RATE=${rate},rows=document.querySelector('#item-rows'),itemsInput=document.querySelector('#items-input'),money=n=>Number(n).toFixed(2),product=id=>PRODUCTS.find(p=>p.id===Number(id));function addRow(){const el=document.createElement('div');el.className='item-row';const wrap=document.createElement('div');wrap.className='item-product';const img=document.createElement('img');img.className='item-image';const fallback=document.createElement('span');fallback.className='item-image fallback';fallback.textContent='✦';const select=document.createElement('select');select.className='product-select';select.setAttribute('aria-label','Məhsul');PRODUCTS.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name+' — '+money(p.price_azn)+' AZN';select.appendChild(o)});wrap.append(img,fallback,select);const size=document.createElement('select');size.className='size-select';size.setAttribute('aria-label','Bədən');const qty=document.createElement('input');qty.className='qty-input';qty.type='number';qty.min='1';qty.max='99';qty.value='1';qty.setAttribute('aria-label','Miqdar');const price=document.createElement('strong');price.className='line-price';const remove=document.createElement('button');remove.type='button';remove.className='icon-button';remove.textContent='Sil';el.append(wrap,size,qty,price,remove);function update(){const p=product(select.value);size.replaceChildren();p.sizes.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;size.appendChild(o)});img.hidden=!p.image_url;fallback.hidden=!!p.image_url;if(p.image_url)img.src=p.image_url;price.textContent=money(p.price_azn*(Number(qty.value)||1))+' AZN';calculate()}img.addEventListener('error',()=>{img.hidden=true;fallback.hidden=false});select.addEventListener('change',update);size.addEventListener('change',calculate);qty.addEventListener('input',update);remove.addEventListener('click',()=>{if(rows.children.length>1){el.remove();calculate()}});rows.appendChild(el);update()}function calculate(){let total=0,items=[];rows.querySelectorAll('.item-row').forEach(el=>{const p=product(el.querySelector('.product-select').value),q=Math.max(1,Math.min(99,Number(el.querySelector('.qty-input').value)||1));total+=p.price_azn*q;items.push({productId:p.id,quantity:q,size:el.querySelector('.size-select').value})});document.querySelector('#total-azn').textContent=money(total)+' AZN';document.querySelector('#total-usd').textContent='$'+money(total/RATE)+' USD';itemsInput.value=JSON.stringify(items)}document.querySelector('#add-item').onclick=addRow;document.querySelector('#order-form').onsubmit=calculate;addRow()</script>`;
  sendHtml(res,200,page('Sifariş ver',content));
}

async function createOrder(req,res){
  const body=await readBody(req),name=clean(body.customer_name,100),phone=clean(body.phone,30),address=clean(body.address,500);let requested=[];try{requested=JSON.parse(body.items||'[]');}catch{}
  if(!name||!phone||!address||!Array.isArray(requested)||requested.length<1||requested.length>10)return sendHtml(res,400,errorPage('Sifarişi yoxlayın','Bütün məlumatları və ən az bir məhsulu daxil edin.'));
  const chosen=[];
  for(const item of requested){const id=Number(item.productId),quantity=Number(item.quantity),size=clean(item.size,20);if(!Number.isInteger(id)||!Number.isInteger(quantity)||quantity<1||quantity>99)return sendHtml(res,400,errorPage('Yanlış miqdar','Miqdar 1–99 arasında olmalıdır.'));const product=db.prepare('SELECT id,name,sizes,price_azn FROM products WHERE id=? AND is_active=1 AND price_azn>0').get(id);if(!product||!parseSizes(product.sizes).includes(size))return sendHtml(res,400,errorPage('Məhsulu yoxlayın','Seçilən məhsul və ya bədən artıq mövcud deyil. Səhifəni yeniləyin.'));chosen.push({product,quantity,size});}
  const total=chosen.reduce((sum,item)=>sum+item.product.price_azn*item.quantity,0),rate=exchangeRate(),t=now();db.exec('BEGIN');
  try{const orderId=Number(db.prepare("INSERT INTO orders(customer_name,phone,address,status,total_azn,exchange_rate,total_usd,created_at,updated_at)VALUES(?,?,?,'new',?,?,?,?,?)").run(name,phone,address,total,rate,total/rate,t,t).lastInsertRowid);const add=db.prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price_azn,quantity,selected_size,line_total_azn)VALUES(?,?,?,?,?,?,?)');for(const item of chosen)add.run(orderId,item.product.id,item.product.name,item.product.price_azn,item.quantity,item.size,item.product.price_azn*item.quantity);db.prepare('INSERT INTO order_status_history(order_id,old_status,new_status,actor,created_at)VALUES(?,NULL,?,?,?)').run(orderId,'new','customer',t);db.exec('COMMIT');redirect(res,`/thank-you?id=${orderId}`);}catch(error){db.exec('ROLLBACK');throw error;}
}
function thankYou(res,url){const order=db.prepare('SELECT id,total_azn,total_usd FROM orders WHERE id=?').get(Number(url.searchParams.get('id')));if(!order)return notFound(res);sendHtml(res,200,page('Sifariş qəbul edildi',`<main class="container narrow"><section class="card centered success"><p class="success-mark">✓</p><h1>Sifarişiniz qəbul edildi</h1><p>Sifariş nömrəniz <strong>#${order.id}</strong>-dir.</p><p>Cəmi: <strong>${money(order.total_azn)} AZN</strong> <small>($${money(order.total_usd)} USD)</small></p><p>Vəziyyət dəyişdikdə sizinlə əlaqə saxlanılacaq.</p><a class="button primary" href="/">Yeni sifariş ver</a></section></main>`));}

function loginPage(res,url){const error=url.searchParams.get('error')?'<p class="alert error">Şifrə düzgün deyil.</p>':'';sendHtml(res,200,page('Admin giriş',`<main class="container narrow"><form class="card login-form" method="post"><p class="eyebrow">MAĞAZA İDARƏETMƏSİ</p><h1>Admin girişi</h1>${error}<label>Şifrə<input type="password" name="password" required autofocus autocomplete="current-password"></label><button class="button primary submit">Daxil ol →</button><a class="text-link" href="/">Müştəri səhifəsi</a></form></main>`));}
async function login(req,res){const body=await readBody(req),given=Buffer.from(String(body.password||'')),expected=Buffer.from(ADMIN_PASSWORD);if(given.length!==expected.length||!crypto.timingSafeEqual(given,expected))return redirect(res,'/admin/login?error=1');const id=crypto.randomBytes(32).toString('hex'),csrf=crypto.randomBytes(24).toString('hex');sessions.set(id,{csrf,expiresAt:Date.now()+12*60*60*1000});res.setHeader('Set-Cookie',`shop_session=${id}; HttpOnly; SameSite=Lax; Path=/; Max-Age=43200`);redirect(res,'/admin');}

function adminOrders(res,url,session){
  const search=clean(url.searchParams.get('q'),100),status=url.searchParams.get('status')||'',filters=[],args=[];if(search){filters.push('(o.customer_name LIKE ? OR o.phone LIKE ?)');args.push(`%${search}%`,`%${search}%`);}if(STATUSES.includes(status)){filters.push('o.status=?');args.push(status);}const where=filters.length?'WHERE '+filters.join(' AND '):'';
  const orders=db.prepare(`SELECT o.*,(SELECT GROUP_CONCAT(product_name||CASE WHEN selected_size<>'' THEN ' ('||selected_size||')' ELSE '' END||' ×'||quantity,', ') FROM order_items WHERE order_id=o.id) AS items FROM orders o ${where} ORDER BY o.created_at DESC`).all(...args);
  const notifications=db.prepare('SELECT n.*,o.customer_name FROM notifications n JOIN orders o ON o.id=n.order_id ORDER BY n.created_at DESC LIMIT 15').all();
  const options=['<option value="">Bütün statuslar</option>',...STATUSES.map(s=>`<option value="${s}" ${s===status?'selected':''}>${STATUS_LABELS[s]}</option>`)].join('');
  const cards=orders.length?orders.map(order=>`<article class="order-card"><div class="order-top"><div><strong>#${order.id}</strong><small>${dateTime(order.created_at)}</small></div><span class="status-badge status-${order.status}">${STATUS_LABELS[order.status]}</span></div><div class="order-details"><div><b>${escapeHtml(order.customer_name)}</b><a href="tel:${escapeAttr(order.phone)}">${escapeHtml(order.phone)}</a><small>${escapeHtml(order.address)}</small></div><div><b>Məhsullar</b><p>${escapeHtml(order.items||'')}</p><strong>${money(order.total_azn)} AZN <small>$${money(order.total_usd)}</small></strong></div></div><div class="status-actions">${statusButtons(order,session)}</div></article>`).join(''):'<section class="empty-state"><span>⌕</span><h2>Sifariş tapılmadı</h2><p>Filtri dəyişib yenidən yoxlayın.</p></section>';
  const noticeList=notifications.length?notifications.map(n=>`<li><strong>#${n.order_id}</strong> — ${escapeHtml(n.message)}<small>${dateTime(n.created_at)} · ${escapeHtml(n.state)}</small></li>`).join(''):'<li class="empty">Hələ bildiriş qeydi yoxdur.</li>';
  sendHtml(res,200,page('Admin · Sifarişlər',adminLayout('Sifarişlər','orders',`<section class="toolbar"><form class="filters"><input name="q" value="${escapeAttr(search)}" placeholder="Ad və ya telefon"><select name="status">${options}</select><button class="button small">Axtar</button><a class="button small secondary" href="/admin">Təmizlə</a></form><a class="button secondary" href="/admin/export.xls">⇩ Excel üçün yüklə</a></section><section class="order-list">${cards}</section><section class="card notifications"><h2>Bildiriş hadisələri</h2><p class="muted">Trial versiyada SMS/WhatsApp göndərilmir; burada gələcək çatdırılma üçün hadisələr saxlanılır.</p><ul class="notification-list">${noticeList}</ul></section>`,session)));
}
function statusButtons(order,session){return STATUSES.map(status=>`<form method="post" action="/admin/orders/${order.id}/status"><input type="hidden" name="csrf" value="${session.csrf}"><input type="hidden" name="status" value="${status}"><button class="status-action status-${status}" ${order.status===status?'disabled':''}>${STATUS_LABELS[status]}</button></form>`).join('');}
async function changeStatus(req,res,route,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const id=Number(route.split('/')[3]),next=String(body.status||''),order=db.prepare('SELECT status FROM orders WHERE id=?').get(id);if(!order)return notFound(res);if(!STATUSES.includes(next))return sendHtml(res,400,errorPage('Yanlış status','Bu status tanınmır.'));if(order.status!==next){const t=now();db.exec('BEGIN');try{db.prepare('UPDATE orders SET status=?,updated_at=? WHERE id=?').run(next,t,id);db.prepare('INSERT INTO order_status_history(order_id,old_status,new_status,actor,created_at)VALUES(?,?,?,?,?)').run(id,order.status,next,'admin',t);const historyId=Number(db.prepare('SELECT last_insert_rowid() id').get().id);mailService.enqueue(id,next,`status-${historyId}`);if(NOTIFIABLE.has(next))db.prepare("INSERT INTO notifications(order_id,status,channel,state,message,created_at)VALUES(?,?,'future-channel','recorded',?,?)").run(id,next,`Bildiriş göndəriləcək: sifariş #${id} → ${STATUS_LABELS[next]}`,t);db.exec('COMMIT');}catch(error){db.exec('ROLLBACK');throw error;}}redirect(res,'/admin');}

function productsPage(res,url,session){
  const editId=Number(url.searchParams.get('edit')),current=editId?db.prepare('SELECT * FROM products WHERE id=?').get(editId):null,products=db.prepare('SELECT * FROM products ORDER BY is_active DESC,name').all();
  const currentSizes=current?parseSizes(current.sizes):SIZE_PRESETS.tops;const selectedPreset=presetFor(currentSizes);
  const productCards=products.map(product=>`<article class="product-card">${imageMarkup(product.image_url,product.name)}<div class="product-card-body"><span class="badge ${product.is_active?'active':'inactive'}">${product.is_active?'Aktiv':'Gizli'}</span><h3>${escapeHtml(product.name)}</h3><p>${escapeHtml(parseSizes(product.sizes).join(' · '))}</p><strong>${money(product.price_azn)} AZN <small class="usd-price">≈ ${money(product.price_azn/exchangeRate())} USD</small></strong><div class="product-actions"><a class="button small secondary" href="/admin/products?edit=${product.id}">Dəyiş</a><form method="post" action="/admin/products/${product.id}/toggle"><input type="hidden" name="csrf" value="${session.csrf}"><button class="button small">${product.is_active?'Gizlət':'Aktiv et'}</button></form><form method="post" action="/admin/products/${product.id}/delete" onsubmit="return confirm('Bu məhsul silinsin? Keçmiş sifarişlər qorunacaq.')"><input type="hidden" name="csrf" value="${session.csrf}"><button class="button small danger">Sil</button></form></div></div></article>`).join('');
  const currentImage=current?.image_url?`<div class="current-image">${imageMarkup(current.image_url,current.name)}<small>Yeni fayl seçilməzsə, bu şəkil qalacaq.</small></div>`:'';
  const form=`<section class="card product-form"><h2>${current?'Məhsulu dəyiş':'Yeni məhsul əlavə et'}</h2><p class="muted">Şəkli birbaşa kompüterdən yükləyin. Məhsul aktiv olduqda müştəri səhifəsində görünür.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="${session.csrf}"><input type="hidden" name="id" value="${current?.id||''}"><label>Məhsul adı<input name="name" required maxlength="100" value="${escapeAttr(current?.name||'')}"></label><label>Açıqlama<textarea name="description" maxlength="300" rows="3">${escapeHtml(current?.description||'')}</textarea></label><label>Standart bədən qrupu<select id="size-preset"><option value="tops" ${selectedPreset==='tops'?'selected':''}>Üst geyim — S, M, L, XL</option><option value="shirts" ${selectedPreset==='shirts'?'selected':''}>Gömlek / oversize — M, L, XL</option><option value="pants" ${selectedPreset==='pants'?'selected':''}>Şalvar / jean — 28, 30, 32, 34, 36</option><option value="one" ${selectedPreset==='one'?'selected':''}>Standart ölçü</option><option value="custom" ${selectedPreset==='custom'?'selected':''}>Xüsusi ölçülər</option></select></label><label>Bədənlər<input id="sizes" name="sizes" required maxlength="100" value="${escapeAttr(currentSizes.join(', '))}" placeholder="S, M, L, XL"></label><label>Məhsul şəkli<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label>${currentImage}<label>Qiymət (AZN)<input name="price_azn" type="number" min="0.01" step="0.01" required value="${current&&current.price_azn>0?escapeAttr(current.price_azn):''}"></label><button class="button primary submit">${current?'Dəyişiklikləri yadda saxla':'Məhsul əlavə et'}</button>${current?'<a class="text-link" href="/admin/products">Ləğv et</a>':''}</form></section>`;
  const script=`<script>const presets=${JSON.stringify(SIZE_PRESETS)};const preset=document.querySelector('#size-preset'),sizes=document.querySelector('#sizes');preset.onchange=()=>{if(preset.value==='custom'){sizes.readOnly=false}else{sizes.value=presets[preset.value].join(', ');sizes.readOnly=true}};preset.onchange()</script>`;
  sendHtml(res,200,page('Admin · Məhsullar',adminLayout('Məhsullar','products',`<div class="product-admin">${form}<section><div class="section-title"><h2>Məhsullar</h2><span>${products.length} məhsul</span></div><div class="product-grid admin-product-grid">${productCards}</div></section></div>${script}`,session)));
}
async function saveProduct(req,res,session,url){
  const body=await readBody(req);
  const id=Number(body.id),name=clean(body.name,100),description=clean(body.description,300),price=Number(body.price_azn),sizes=[...new Set(String(body.sizes||'').split(',').map(s=>s.trim()).filter(Boolean))];
  if(!name||!Number.isFinite(price)||price<=0||!sizes.length)return sendHtml(res,400,errorPage('Məhsulu yoxlayın','Ad, düzgün qiymət və ən az bir bədən daxil edin.'));
  let image='';try{if(body.image?.data)image=saveImage(body.image);}catch(error){return sendHtml(res,400,errorPage('Şəkil yüklənmədi',error.message));}
  const t=now();if(id){const old=db.prepare('SELECT * FROM products WHERE id=?').get(id);if(!old)return notFound(res);db.prepare('UPDATE products SET name=?,description=?,sizes=?,image_url=?,price_azn=?,updated_at=? WHERE id=?').run(name,description,JSON.stringify(sizes),image||old.image_url,price,t,id);if(image)removeStoredImage(old.image_url);}else db.prepare('INSERT INTO products(name,description,sizes,image_url,price_azn,is_active,created_at,updated_at)VALUES(?,?,?,?,?,1,?,?)').run(name,description,JSON.stringify(sizes),image,price,t,t);redirect(res,'/admin/products');
}
async function toggleProduct(req,res,route,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const id=Number(route.split('/')[3]),product=db.prepare('SELECT is_active FROM products WHERE id=?').get(id);if(!product)return notFound(res);db.prepare('UPDATE products SET is_active=?,updated_at=? WHERE id=?').run(product.is_active?0:1,now(),id);redirect(res,'/admin/products');}
async function deleteProduct(req,res,route,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const id=Number(route.split('/')[3]),product=db.prepare('SELECT image_url FROM products WHERE id=?').get(id);if(!product)return notFound(res);db.exec('BEGIN');try{db.prepare('UPDATE order_items SET product_id=NULL WHERE product_id=?').run(id);db.prepare('DELETE FROM products WHERE id=?').run(id);db.exec('COMMIT');removeStoredImage(product.image_url);}catch(error){db.exec('ROLLBACK');throw error;}redirect(res,'/admin/products');}

function settingsPage(res,url,session){const saved=url.searchParams.get('saved')?'<p class="alert success-alert">Məzənnə yadda saxlanıldı.</p>':'',rate=exchangeRate();sendHtml(res,200,page('Admin · Ayarlar',adminLayout('Ayarlar','settings',`<section class="card settings-card"><h2>Məzənnə</h2>${saved}<p class="muted">1 USD üçün AZN məbləği. Müştəri ekranında USD = AZN ÷ məzənnə hesablanır.</p><form method="post"><input type="hidden" name="csrf" value="${session.csrf}"><label>1 USD = neçə AZN?<input name="exchange_rate" type="number" min="0.01" max="100" step="0.01" required value="${escapeAttr(rate)}"></label><button class="button primary submit">Yadda saxla</button></form></section>${mailSettingsPanel(session)}`,session)));}
async function saveSettings(req,res,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const rate=Number(body.exchange_rate);if(!Number.isFinite(rate)||rate<=0||rate>100)return sendHtml(res,400,errorPage('Məzənnəni yoxlayın','0.01 ilə 100 arasında düzgün rəqəm yazın.'));db.prepare("UPDATE settings SET value=?,updated_at=? WHERE key='exchange_rate'").run(rate.toFixed(2),now());redirect(res,'/admin/settings?saved=1');}
function exportOrders(res){const orders=db.prepare(`SELECT o.*,GROUP_CONCAT(oi.product_name||CASE WHEN oi.selected_size<>'' THEN ' ('||oi.selected_size||')' ELSE '' END||' x'||oi.quantity,', ')items FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC`).all(),header=['Sifariş #','Tarix','Müştəri','Telefon','Ünvan','Məhsullar','Status','AZN','USD','Məzənnə'];const xml=`<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Sifarişlər"><Table><Row>${header.map(xmlCell).join('')}</Row>${orders.map(o=>`<Row>${[o.id,dateTime(o.created_at),o.customer_name,o.phone,o.address,o.items||'',STATUS_LABELS[o.status],money(o.total_azn),money(o.total_usd),money(o.exchange_rate)].map(xmlCell).join('')}</Row>`).join('')}</Table></Worksheet></Workbook>`;res.writeHead(200,{'Content-Type':'application/vnd.ms-excel; charset=utf-8','Content-Disposition':'attachment; filename="orders-export.xls"'});res.end(xml);}

function adminLayout(title,active,body,session){const nav=[['orders','/admin','Sifarişlər'],['products','/admin/products','Məhsullar'],['settings','/admin/settings','Ayarlar']].map(([id,href,label])=>`<a class="${active===id?'selected':''}" href="${href}">${label}</a>`).join('');return `<div class="admin-shell"><header class="admin-header"><a class="brand" href="/admin">AUREN FASHION <span>paneli</span></a><nav>${nav}</nav><form method="post" action="/admin/logout"><input type="hidden" name="csrf" value="${session.csrf}"><button class="logout">Çıxış</button></form></header><main class="admin-content"><div class="page-heading"><p class="eyebrow">İDARƏETMƏ</p><h1>${title}</h1></div>${body}</main></div>`;}

function requireAdmin(req,res){const token=parseCookies(req.headers.cookie).shop_session,session=token&&sessions.get(token);if(!session||session.expiresAt<Date.now()){if(token)sessions.delete(token);redirect(res,'/admin/login');return null;}return session;}
async function logout(req,res,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const token=parseCookies(req.headers.cookie).shop_session;if(token)sessions.delete(token);res.setHeader('Set-Cookie','shop_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0');redirect(res,'/admin/login');}
function validCsrf(body,session){const actual=Buffer.from(String(body.csrf||'')),expected=Buffer.from(session.csrf);return actual.length===expected.length&&crypto.timingSafeEqual(actual,expected);}
function exchangeRate(){return Number(db.prepare("SELECT value FROM settings WHERE key='exchange_rate'").get().value);}
function now(){return new Date().toISOString();}
function clean(value,max){return String(value||'').trim().replace(/\s+/g,' ').slice(0,max);}
function money(value){return Number(value).toFixed(2);}
function parseSizes(value){try{const sizes=Array.isArray(value)?value:JSON.parse(value||'[]');return Array.isArray(sizes)?sizes.map(size=>String(size).trim()).filter(Boolean):[];}catch{return [];}}
function presetFor(sizes){return Object.entries(SIZE_PRESETS).find(([,preset])=>preset.join(',')===sizes.join(','))?.[0]||'custom';}
function saveImage(file){if(file.data.length>5*1024*1024)throw Error('Şəkil 5 MB-dan kiçik olmalıdır.');const extension=imageExtension(file.data);if(!extension)throw Error('Yalnız JPG, PNG, WEBP və GIF şəkilləri yüklənə bilər.');const filename=`${crypto.randomUUID()}${extension}`;fs.writeFileSync(path.join(UPLOADS_DIR,filename),file.data,{flag:'wx'});return `/uploads/${filename}`;}
function imageExtension(data){if(data[0]===0xff&&data[1]===0xd8&&data[2]===0xff)return '.jpg';if(data.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))return '.png';if(data.subarray(0,4).toString()==='RIFF'&&data.subarray(8,12).toString()==='WEBP')return '.webp';if(data.subarray(0,3).toString()==='GIF')return '.gif';return '';}
function removeStoredImage(imagePath){if(!String(imagePath).startsWith('/uploads/'))return;const filename=path.basename(imagePath);if(/^[a-f0-9-]+\.(jpg|png|webp|gif)$/.test(filename))fs.rmSync(path.join(UPLOADS_DIR,filename),{force:true});}
function serveUpload(res,route){const filename=path.basename(decodeURIComponent(route));if(!/^[a-f0-9-]+\.(jpg|png|webp|gif)$/.test(filename))return notFound(res);const type={jpg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif'}[filename.split('.').pop()];serveFile(res,path.join(UPLOADS_DIR,filename),type);}
function imageMarkup(src,alt){return src?`<img class="product-image" src="${escapeAttr(src)}" alt="${escapeAttr(alt)}" loading="lazy">`:'<div class="product-image placeholder">Görsel<br>yoxdur</div>';}

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function escapeAttr(value){return escapeHtml(value);}
function xmlCell(value){return `<Cell><Data ss:Type="String">${escapeHtml(value)}</Data></Cell>`;}
function dateTime(iso){return new Intl.DateTimeFormat('az-AZ',{dateStyle:'short',timeStyle:'short'}).format(new Date(iso));}
function page(title,body){return `<!doctype html><html lang="az"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#202c48"><title>${escapeHtml(title)}</title><link rel="stylesheet" href="/styles.css"></head><body class="${body.includes('class="shop-header"')?'auren-store':''}">${body}</body></html>`;}
function errorPage(title,message){return page(title,`<main class="container narrow"><section class="card centered"><h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p><a class="button primary" href="/">Ana səhifə</a></section></main>`);}
function parseCookies(header=''){return Object.fromEntries(header.split(';').map(part=>part.trim()).filter(Boolean).map(part=>{const index=part.indexOf('=');return [part.slice(0,index),decodeURIComponent(part.slice(index+1))];}));}
function readBody(req){return new Promise((resolve,reject)=>{const chunks=[];let length=0;req.on('data',chunk=>{length+=chunk.length;if(length>30*1024*1024){reject(Error('Request too large'));req.destroy();}else chunks.push(chunk);});req.on('end',()=>{const data=Buffer.concat(chunks),contentType=req.headers['content-type']||'';resolve(contentType.startsWith('multipart/form-data')?parseMultipart(data,contentType):Object.fromEntries(new URLSearchParams(data.toString('utf8'))));});req.on('error',reject);});}
function parseMultipart(data,contentType){const match=contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/i);if(!match)throw Error('Şəkil yükləmə sərhədi tapılmadı.');const boundary='--'+(match[1]||match[2]).trim(),result={};for(const part of data.toString('latin1').split(boundary)){let divider=part.indexOf('\r\n\r\n'),separator='\r\n\r\n';if(divider<0){divider=part.indexOf('\n\n');separator='\n\n';}if(divider<0)continue;const headers=part.slice(0,divider),nameMatch=headers.match(/name=(?:"([^"]+)"|([^;\s\r\n]+))/i),fileMatch=headers.match(/filename=(?:"([^"]*)"|([^;\s\r\n]+))/i),name=nameMatch?.[1]||nameMatch?.[2],filename=fileMatch?.[1]||fileMatch?.[2];if(!name)continue;let payload=part.slice(divider+separator.length);payload=payload.replace(/\r?\n$/,'');if(filename)result[name]={filename:path.basename(filename),data:Buffer.from(payload,'latin1')};else result[name]=Buffer.from(payload,'latin1').toString('utf8');}return result;}
function serveFile(res,file,type){fs.readFile(file,(error,data)=>{if(error)return notFound(res);res.writeHead(200,{'Content-Type':type,'Cache-Control':'public, max-age=3600','X-Content-Type-Options':'nosniff'});res.end(data);});}
function sendHtml(res,status,content){res.writeHead(status,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'});res.end(content);}
function sendText(res,status,content){res.writeHead(status,{'Content-Type':'text/plain; charset=utf-8'});res.end(content);}
function redirect(res,location){res.writeHead(303,{Location:location,'Cache-Control':'no-store'});res.end();}
function forbidden(res){return sendHtml(res,403,errorPage('Giriş rədd edildi','Təhlükəsizlik yoxlaması alınmadı.'))}
function notFound(res){return sendHtml(res,404,errorPage('Səhifə tapılmadı','Axtardığınız səhifə mövcud deyil.'))}
function loadEnv(file){if(!fs.existsSync(file))return;fs.readFileSync(file,'utf8').replace(/^\uFEFF/,'').split(/\r?\n/).forEach(line=>{const match=line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*)\s*$/);if(match&&!process.env[match[1]])process.env[match[1]]=match[2].replace(/^['"]|['"]$/g,'');});}

// Store enhancements: variant-level stock, product galleries, cart and checkout.
setupStoreTables();
function setupStoreTables(){
  db.exec(`CREATE TABLE IF NOT EXISTS product_variants(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,size TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),UNIQUE(product_id,size));CREATE TABLE IF NOT EXISTS product_images(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,image_url TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0);CREATE INDEX IF NOT EXISTS variants_product ON product_variants(product_id);CREATE INDEX IF NOT EXISTS images_product ON product_images(product_id);`);
  addColumnIfMissing('orders','email',"email TEXT NOT NULL DEFAULT ''");
  const all=db.prepare('SELECT id,sizes,image_url FROM products').all(),variant=db.prepare('SELECT 1 FROM product_variants WHERE product_id=? AND size=?'),add=db.prepare('INSERT INTO product_variants(product_id,size,stock)VALUES(?,?,0)'),hasImages=db.prepare('SELECT 1 FROM product_images WHERE product_id=? LIMIT 1'),addImage=db.prepare('INSERT INTO product_images(product_id,image_url,position)VALUES(?,?,0)');
  for(const p of all){for(const size of parseSizes(p.sizes))if(!variant.get(p.id,size))add.run(p.id,size);if(p.image_url&&!hasImages.get(p.id))addImage.run(p.id,p.image_url);}
}
function variantsFor(productId){return db.prepare('SELECT id,size,stock FROM product_variants WHERE product_id=? ORDER BY id').all(productId);}
function imagesFor(productId){return db.prepare('SELECT image_url FROM product_images WHERE product_id=? ORDER BY position,id').all(productId).map(x=>x.image_url);}
function productCard(product){const stock=variantsFor(product.id).reduce((sum,x)=>sum+x.stock,0),image=imagesFor(product.id)[0]||product.image_url;return `<a class="store-card" href="/product/${product.id}">${imageMarkup(image,product.name)}<div><h3>${escapeHtml(product.name)}</h3><p>${stock>0?`${stock} ədəd stokda`:'Stokda yoxdur'}</p><strong>${money(product.price_azn)} AZN <small class="usd-price">≈ ${money(product.price_azn/exchangeRate())} USD</small></strong></div></a>`;}
customerPage=function(res){const products=db.prepare('SELECT id,name,description,sizes,image_url,price_azn FROM products WHERE is_active=1 AND price_azn>0 ORDER BY id DESC').all(),cards=products.map(productCard).join('')||'<p class="muted">Hazırda məhsul yoxdur.</p>';sendHtml(res,200,page('AUREN FASHION',`<header class="shop-header"><a href="/" class="shop-logo">AUREN <span>FASHION</span></a><a class="cart-link" href="/checkout">Səbət <b id="cart-count">0</b></a></header><main class="shop-main"><section class="shop-hero"><p>YENİ KOLLEKSİYA</p><h1>Zəriflik hər detalda.</h1></section><section><div class="section-title"><h2>İlanlar</h2><span>Sağa sürüşdürərək bax</span></div><div class="store-rail">${cards}</div></section><section class="auren-campaign" aria-label="AUREN FASHION kolleksiyası"><img src="/auren-fashion-banner.png" alt="AUREN FASHION — zərif qara geyim və açıq rəngli kostyumla moda kolleksiyası" width="1774" height="887" loading="lazy" decoding="async"></section></main><script>const c=JSON.parse(localStorage.getItem('shop_cart')||'[]');document.querySelector('#cart-count').textContent=c.reduce((s,x)=>s+x.quantity,0)</script>`));};
function productDetail(res,route){const id=Number(route.split('/')[2]),p=db.prepare('SELECT * FROM products WHERE id=? AND is_active=1 AND price_azn>0').get(id);if(!p)return notFound(res);const images=imagesFor(id);if(!images.length&&p.image_url)images.push(p.image_url);const variants=variantsFor(id),data=JSON.stringify({id:p.id,name:p.name,price:p.price_azn,image:images[0]||'',variants}).replace(/</g,'\\u003c'),thumbs=images.map((src,i)=>`<button class="gallery-thumb ${i?'':'active'}" data-image="${escapeAttr(src)}">${imageMarkup(src,`${p.name} ${i+1}`)}</button>`).join('');const options=variants.map(v=>`<button class="size-choice ${v.stock?'':'sold'}" data-size="${escapeAttr(v.size)}" data-stock="${v.stock}" ${v.stock?'':'disabled'}>${escapeHtml(v.size)}<small>${v.stock?'':'Tükəndi'}</small></button>`).join('');sendHtml(res,200,page(p.name,`<header class="shop-header"><a href="/" class="shop-logo">AUREN <span>FASHION</span></a><a class="cart-link" href="/checkout">Səbət <b id="cart-count">0</b></a></header><main class="detail"><a class="back-link" href="/">← Bütün məhsullar</a><section class="product-detail"><div class="gallery"><div class="gallery-main">${images[0]?`<img id="main-image" src="${escapeAttr(images[0])}" alt="${escapeAttr(p.name)}">`:'<div class="product-image placeholder">Görsel yoxdur</div>'}</div><div class="gallery-thumbs">${thumbs}</div></div><div class="product-info"><p class="eyebrow">MƏHSUL DETALI</p><h1>${escapeHtml(p.name)}</h1><strong class="detail-price">${money(p.price_azn)} AZN <small class="usd-price">≈ ${money(p.price_azn/exchangeRate())} USD</small></strong><p>${escapeHtml(p.description||'')}</p><div><b>Bədən seçin</b><div class="size-choices">${options}</div><small id="stock-note">Bədən seçin</small></div><div class="buy-row"><label>Miqdar<input id="qty" type="number" min="1" value="1" disabled></label><button id="add-cart" class="button primary" disabled>Səbətə əlavə et</button></div></div></section></main><script>const PRODUCT=${data};let selected=null;const cart=()=>JSON.parse(localStorage.getItem('shop_cart')||'[]');const save=x=>localStorage.setItem('shop_cart',JSON.stringify(x));const count=()=>document.querySelector('#cart-count').textContent=cart().reduce((s,x)=>s+x.quantity,0);count();document.querySelectorAll('.gallery-thumb').forEach(x=>x.onclick=()=>{document.querySelectorAll('.gallery-thumb').forEach(y=>y.classList.remove('active'));x.classList.add('active');document.querySelector('#main-image').src=x.dataset.image});document.querySelectorAll('.size-choice').forEach(x=>x.onclick=()=>{document.querySelectorAll('.size-choice').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');selected={size:x.dataset.size,stock:Number(x.dataset.stock)};document.querySelector('#qty').disabled=false;document.querySelector('#qty').max=selected.stock;document.querySelector('#qty').value=1;document.querySelector('#add-cart').disabled=false;document.querySelector('#stock-note').textContent=selected.stock+' ədəd stokda'});document.querySelector('#add-cart').onclick=()=>{const q=Math.max(1,Math.min(selected.stock,Number(document.querySelector('#qty').value)||1));const items=cart(),old=items.find(x=>x.productId===PRODUCT.id&&x.size===selected.size);if(old)old.quantity=Math.min(selected.stock,old.quantity+q);else items.push({productId:PRODUCT.id,name:PRODUCT.name,price:PRODUCT.price,image:PRODUCT.image,size:selected.size,quantity:q});save(items);count();document.querySelector('#add-cart').textContent='Səbətə əlavə edildi ✓';setTimeout(()=>document.querySelector('#add-cart').textContent='Səbətə əlavə et',900)}</script>`));}
function checkoutPage(res){sendHtml(res,200,page('Səbət',`<header class="shop-header"><a href="/" class="shop-logo">AUREN <span>FASHION</span></a><a class="cart-link" href="/">Mağazaya qayıt</a></header><main class="checkout"><h1>Səbətim</h1><div id="cart-items" class="cart-items"></div><form class="card checkout-form" method="post" id="checkout-form"><input type="hidden" name="items" id="checkout-items"><h2>Çatdırılma və fatura məlumatları</h2><label>Ad və soyad<input name="customer_name" required maxlength="100" autocomplete="name"></label><label>Telefon nömrəsi<input name="phone" required pattern="[0-9+() -]{7,30}" inputmode="tel" placeholder="050 123 45 67"></label><label>E-poçt ünvanı<input name="email" required type="email" maxlength="160" autocomplete="email" placeholder="ad@example.com"></label><label>Ünvan<textarea name="address" required maxlength="500" rows="3"></textarea></label><button class="button primary submit">Sifarişi tamamla</button></form></main><script>const usdRate=${exchangeRate()};let items=JSON.parse(localStorage.getItem('shop_cart')||'[]');const money=x=>Number(x).toFixed(2),box=document.querySelector('#cart-items');function draw(){if(!items.length){box.innerHTML='<section class="empty-state"><h2>Səbət boşdur</h2><a class="button primary" href="/">Məhsullara bax</a></section>';document.querySelector('#checkout-form').hidden=true;return}box.innerHTML=items.map((x,i)=>'<article class="cart-item">'+(x.image?'<img src="'+x.image+'" alt="">':'<div class="cart-image">✦</div>')+'<div><b>'+x.name+'</b><small>Bədən: '+x.size+'</small><strong>'+money(x.price)+' AZN × '+x.quantity+'</strong><small>≈ $'+money(x.price*x.quantity/usdRate)+' USD</small></div><button data-i="'+i+'">Sil</button></article>').join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{items.splice(Number(b.dataset.i),1);localStorage.setItem('shop_cart',JSON.stringify(items));draw()});document.querySelector('#checkout-items').value=JSON.stringify(items)}draw();document.querySelector('#checkout-form').onsubmit=()=>document.querySelector('#checkout-items').value=JSON.stringify(items)</script>`));}
async function checkout(req,res){const body=await readBody(req),name=clean(body.customer_name,100),phone=clean(body.phone,30),email=clean(body.email,160).toLowerCase(),address=clean(body.address,500);let items=[];try{items=JSON.parse(body.items||'[]')}catch{}if(!name||!phone||!email||!validEmail(email)||!address||!Array.isArray(items)||!items.length)return sendHtml(res,400,errorPage('Sifarişi yoxlayın','Ad, telefon, e-poçt, ünvan və ən az bir məhsul vacibdir.'));const unique=new Map();for(const x of items){const key=`${Number(x.productId)}:${clean(x.size,20)}`,q=Number(x.quantity);if(!Number.isInteger(q)||q<1||q>99)return sendHtml(res,400,errorPage('Yanlış miqdar','Miqdar düzgün deyil.'));unique.set(key,{id:Number(x.productId),size:clean(x.size,20),quantity:(unique.get(key)?.quantity||0)+q});}const chosen=[];db.exec('BEGIN');try{for(const item of unique.values()){const p=db.prepare('SELECT id,name,price_azn FROM products WHERE id=? AND is_active=1 AND price_azn>0').get(item.id),v=db.prepare('SELECT id,stock FROM product_variants WHERE product_id=? AND size=?').get(item.id,item.size);if(!p||!v||v.stock<item.quantity)throw Error(`${p?.name||'Məhsul'} (${item.size}) stokda yoxdur.`);const changed=db.prepare('UPDATE product_variants SET stock=stock-? WHERE id=? AND stock>=?').run(item.quantity,v.id,item.quantity);if(!changed.changes)throw Error('Stok yeniləndi; səbəti yeniləyin.');chosen.push({...item,p});}const total=chosen.reduce((s,x)=>s+x.p.price_azn*x.quantity,0),rate=exchangeRate(),t=now(),orderId=Number(db.prepare("INSERT INTO orders(customer_name,phone,email,address,status,total_azn,exchange_rate,total_usd,created_at,updated_at)VALUES(?,?,?,?, 'new',?,?,?,?,?)").run(name,phone,email,address,total,rate,total/rate,t,t).lastInsertRowid),add=db.prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price_azn,quantity,selected_size,line_total_azn)VALUES(?,?,?,?,?,?,?)');for(const x of chosen)add.run(orderId,x.p.id,x.p.name,x.p.price_azn,x.quantity,x.size,x.p.price_azn*x.quantity);db.prepare('INSERT INTO order_status_history(order_id,old_status,new_status,actor,created_at)VALUES(?,NULL,?,?,?)').run(orderId,'new','customer',t);mailService.enqueue(orderId,'new',`order-${orderId}`);db.exec('COMMIT');sendHtml(res,200,page('Sifariş qəbul edildi',`<main class="container narrow"><section class="card centered success"><p class="success-mark">✓</p><h1>Sifarişiniz qəbul edildi</h1><p>Sifariş nömrəniz <strong>#${orderId}</strong>-dir.</p><p>Sifariş təsdiqi e-poçt ünvanınıza göndərilmək üçün qeydə alındı.</p><a class="button primary" href="/">Mağazaya qayıt</a></section><script>localStorage.removeItem('shop_cart')</script></main>`));}catch(error){db.exec('ROLLBACK');return sendHtml(res,400,errorPage('Sifariş tamamlanmadı',error.message));}}
productsPage=function(res,url,session){const edit=Number(url.searchParams.get('edit')),current=edit?db.prepare('SELECT * FROM products WHERE id=?').get(edit):null,products=db.prepare('SELECT * FROM products ORDER BY is_active DESC,name').all(),sizes=current?parseSizes(current.sizes):SIZE_PRESETS.tops,stock=Object.fromEntries(current?variantsFor(current.id).map(v=>[v.size,v.stock]):sizes.map(s=>[s,0]));const cards=products.map(p=>`<article class="product-card">${imageMarkup(imagesFor(p.id)[0]||p.image_url,p.name)}<div class="product-card-body"><span class="badge ${p.is_active?'active':'inactive'}">${p.is_active?'Aktiv':'Gizli'}</span><h3>${escapeHtml(p.name)}</h3><p>${variantsFor(p.id).map(v=>`${v.size}: ${v.stock}`).join(' · ')}</p><strong>${money(p.price_azn)} AZN <small class="usd-price">≈ ${money(p.price_azn/exchangeRate())} USD</small></strong><div class="product-actions"><a class="button small secondary" href="/admin/products?edit=${p.id}">Dəyiş</a><form method="post" action="/admin/products/${p.id}/toggle"><input type="hidden" name="csrf" value="${session.csrf}"><button class="button small">${p.is_active?'Gizlət':'Aktiv et'}</button></form><form method="post" action="/admin/products/${p.id}/delete"><input type="hidden" name="csrf" value="${session.csrf}"><button class="button small danger">Sil</button></form></div></div></article>`).join('');sendHtml(res,200,page('Admin · Məhsullar',adminLayout('Məhsullar','products',`<div class="product-admin"><section class="card product-form"><h2>${current?'Məhsulu dəyiş':'Yeni məhsul'}</h2>${url.searchParams.get('image_deleted')==='1'?'<p class="alert success-alert" role="status">Şəkil silindi.</p>':''}${productImagesEditor(current,session)}<form method="post" enctype="multipart/form-data"><input name="csrf" type="hidden" value="${session.csrf}"><input name="id" type="hidden" value="${current?.id||''}"><label>Ad<input name="name" required value="${escapeAttr(current?.name||'')}"></label><label>Açıqlama<textarea name="description">${escapeHtml(current?.description||'')}</textarea></label><label>Bədənlər (vergüllə)<input id="sizes" name="sizes" value="${escapeAttr(sizes.join(', '))}" required></label><div><b>Hər bədən üçün stok</b><div id="stock-inputs"></div></div><input id="stocks" name="stocks" type="hidden" value="${escapeAttr(JSON.stringify(stock))}"><label>Yeni şəkillər (ayrı-ayrı seçib əlavə edə bilərsiniz)<input name="images" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><label>Qiymət AZN<input name="price_azn" type="number" min="0.01" step="0.01" required value="${current?.price_azn||''}"></label><button class="button primary submit">Yadda saxla</button></form></section><section><div class="section-title"><h2>Məhsullar</h2><span>${products.length}</span></div><div class="product-grid admin-product-grid">${cards}</div></section></div><script>const field=document.querySelector('#sizes'),out=document.querySelector('#stock-inputs'),hidden=document.querySelector('#stocks');let saved=JSON.parse(hidden.value||'{}');function render(){let sizes=field.value.split(',').map(x=>x.trim()).filter(Boolean);out.innerHTML=sizes.map(x=>'<label class="stock-field">'+x+'<input type="number" min="0" value="'+(saved[x]??0)+'" data-size="'+x+'"></label>').join('');out.querySelectorAll('input').forEach(x=>x.oninput=()=>{saved[x.dataset.size]=Math.max(0,Number(x.value)||0);hidden.value=JSON.stringify(saved)})}field.onchange=render;render()</script>`,session)));};
saveProduct=async function(req,res,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const id=Number(body.id),name=clean(body.name,100),description=clean(body.description,300),price=Number(body.price_azn),sizes=[...new Set(String(body.sizes||'').split(',').map(x=>x.trim()).filter(Boolean))];let stocks={};try{stocks=JSON.parse(body.stocks||'{}')}catch{}if(!name||!sizes.length||!Number.isFinite(price)||price<=0)return sendHtml(res,400,errorPage('Məhsulu yoxlayın','Ad, qiymət və bədənlər vacibdir.'));const files=Array.isArray(body.images)?body.images:body.images?[body.images]:[],uploaded=[];try{for(const file of files)if(file?.data)uploaded.push(saveImage(file));}catch(error){return sendHtml(res,400,errorPage('Şəkil yüklənmədi',error.message));}const t=now();let productId=id;if(id){const old=db.prepare('SELECT id FROM products WHERE id=?').get(id);if(!old)return notFound(res);db.prepare('UPDATE products SET name=?,description=?,sizes=?,price_azn=?,updated_at=? WHERE id=?').run(name,description,JSON.stringify(sizes),price,t,id);}else productId=Number(db.prepare('INSERT INTO products(name,description,sizes,image_url,price_azn,is_active,created_at,updated_at)VALUES(?,?,?,?,?,1,?,?)').run(name,description,JSON.stringify(sizes),uploaded[0]||'',price,t,t).lastInsertRowid);if(uploaded.length){const start=db.prepare('SELECT COALESCE(MAX(position),-1)+1 p FROM product_images WHERE product_id=?').get(productId).p,add=db.prepare('INSERT INTO product_images(product_id,image_url,position)VALUES(?,?,?)');uploaded.forEach((url,i)=>add.run(productId,url,start+i));db.prepare('UPDATE products SET image_url=? WHERE id=?').run(imagesFor(productId)[0]||'',productId);}db.prepare('DELETE FROM product_variants WHERE product_id=?').run(productId);const addVariant=db.prepare('INSERT INTO product_variants(product_id,size,stock)VALUES(?,?,?)');for(const size of sizes)addVariant.run(productId,size,Math.max(0,Number(stocks[size])||0));redirect(res,'/admin/products');};
deleteProduct=async function(req,res,route,session){const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);const id=Number(route.split('/')[3]),product=db.prepare('SELECT image_url FROM products WHERE id=?').get(id);if(!product)return notFound(res);const images=imagesFor(id);db.exec('BEGIN');try{db.prepare('UPDATE order_items SET product_id=NULL WHERE product_id=?').run(id);db.prepare('DELETE FROM products WHERE id=?').run(id);db.exec('COMMIT');for(const image of images)removeStoredImage(image);removeStoredImage(product.image_url);}catch(error){db.exec('ROLLBACK');throw error;}redirect(res,'/admin/products');};
parseMultipart=function(data,contentType){const match=contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/i);if(!match)throw Error('Yükləmə sərhədi tapılmadı.');const boundary='--'+(match[1]||match[2]).trim(),result={};for(const part of data.toString('latin1').split(boundary)){let divider=part.indexOf('\r\n\r\n'),separator='\r\n\r\n';if(divider<0){divider=part.indexOf('\n\n');separator='\n\n';}if(divider<0)continue;const headers=part.slice(0,divider),nameMatch=headers.match(/name=(?:"([^"]+)"|([^;\s\r\n]+))/i),fileMatch=headers.match(/filename=(?:"([^"]*)"|([^;\s\r\n]+))/i),name=nameMatch?.[1]||nameMatch?.[2],filename=fileMatch?.[1]||fileMatch?.[2];if(!name)continue;let value=part.slice(divider+separator.length).replace(/\r?\n$/,'');const entry=filename?{filename:path.basename(filename),data:Buffer.from(value,'latin1')}:Buffer.from(value,'latin1').toString('utf8');if(result[name]===undefined)result[name]=entry;else result[name]=Array.isArray(result[name])?[...result[name],entry]:[result[name],entry];}return result;};
const originalPage=page;page=(title,body)=>originalPage(title,body).replace('</head>','<link rel="stylesheet" href="/store.css"><script src="/product-tools.js" defer></script></head>');
const styledPage=page;page=(title,body)=>{const safeBody=body.replace(/<input name="phone"[^>]*>/g,'<input name="phone" required type="text" inputmode="numeric" pattern="[0-9]{7,15}" minlength="7" maxlength="15" autocomplete="tel" placeholder="0501234567">');return styledPage(title,safeBody).replace('</body>','<script>document.addEventListener("input",e=>{if(e.target&&e.target.name==="phone")e.target.value=e.target.value.replace(/\\D/g,"").slice(0,15)})</script></body>');};
const originalReadBody=readBody;readBody=async req=>{const body=await originalReadBody(req);if(body.phone!==undefined)body.phone=String(body.phone).replace(/\D/g,'').slice(0,15);return body;};

// Lightweight, progressive visual feedback shared by the storefront and admin pages.
const interactivePage=page;page=(title,body)=>interactivePage(title,body).replace('</body>',`<script>document.querySelectorAll('.store-card,.product-card,.order-card,.cart-item,.gallery,.product-info,.checkout-form').forEach((el,index)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',Math.min(index*45,270)+'ms')});document.addEventListener('pointerdown',event=>{const control=event.target.closest('.button,.cart-link,.size-choice,.gallery-thumb');if(!control||control.disabled)return;const rect=control.getBoundingClientRect(),ripple=document.createElement('span');ripple.className='tap-ripple';ripple.style.left=(event.clientX-rect.left)+'px';ripple.style.top=(event.clientY-rect.top)+'px';control.append(ripple);ripple.addEventListener('animationend',()=>ripple.remove())});</script></body>`);

adminOrders=function(res,url,session){
  const search=clean(url.searchParams.get('q'),100),status=url.searchParams.get('status')||'',filters=[],args=[];
  if(search){filters.push('(o.customer_name LIKE ? OR o.phone LIKE ? OR o.email LIKE ?)');args.push(`%${search}%`,`%${search}%`,`%${search}%`);}
  if(STATUSES.includes(status)){filters.push('o.status=?');args.push(status);}
  const where=filters.length?'WHERE '+filters.join(' AND '):'';
  const orders=db.prepare(`SELECT o.*,(SELECT GROUP_CONCAT(product_name||CASE WHEN selected_size<>'' THEN ' ('||selected_size||')' ELSE '' END||' ×'||quantity,', ') FROM order_items WHERE order_id=o.id) AS items FROM orders o ${where} ORDER BY o.created_at DESC`).all(...args);
  const options=['<option value="">Bütün statuslar</option>',...STATUSES.map(s=>`<option value="${s}" ${s===status?'selected':''}>${STATUS_LABELS[s]}</option>`)].join('');
  const cards=orders.length?orders.map(order=>`<article class="order-card"><div class="order-top"><div><strong>#${order.id}</strong><small>${dateTime(order.created_at)}</small></div><span class="status-badge status-${order.status}">${STATUS_LABELS[order.status]}</span></div><div class="order-details"><div><b>${escapeHtml(order.customer_name)}</b><a href="tel:${escapeAttr(order.phone)}">${escapeHtml(order.phone)}</a>${order.email?`<a class="email-link" href="mailto:${escapeAttr(order.email)}">${escapeHtml(order.email)}</a>`:''}<small>${escapeHtml(order.address)}</small></div><div><b>Məhsullar</b><p>${escapeHtml(order.items||'')}</p><strong>${money(order.total_azn)} AZN <small>$${money(order.total_usd)}</small></strong></div></div><div class="status-actions">${statusButtons(order,session)}</div></article>`).join(''):'<section class="empty-state"><span>⌕</span><h2>Sifariş tapılmadı</h2><p>Filtri dəyişib yenidən yoxlayın.</p></section>';
  sendHtml(res,200,page('Admin · Sifarişlər',adminLayout('Sifarişlər','orders',`<section class="toolbar"><form class="filters"><input name="q" value="${escapeAttr(search)}" placeholder="Ad, telefon və ya e-poçt"><select name="status">${options}</select><button class="button small">Axtar</button><a class="button small secondary" href="/admin">Təmizlə</a></form><a class="button secondary" href="/admin/export.xls">⇩ Excel üçün yüklə</a></section><section class="order-list">${cards}</section>`,session)));
};

function productImagesEditor(product,session){
  if(!product)return '';
  const images=db.prepare('SELECT id,image_url FROM product_images WHERE product_id=? ORDER BY position,id').all(product.id);
  return `<section class="existing-images" aria-label="Məhsul şəkilləri"><h3>Mövcud şəkillər</h3><p class="muted">${images.length?'Silmək istədiyiniz şəklin altındakı düyməni basın. Dəyişdirdiyiniz məhsul məlumatlarını əvvəlcə yadda saxlayın.':'Bu məhsulun şəkli yoxdur. Aşağıdan yeni şəkil əlavə edə bilərsiniz.'}</p><div class="existing-image-grid">${images.map((image,index)=>`<div class="existing-image-card">${imageMarkup(image.image_url,`${product.name} — şəkil ${index+1}`)}<small>${index===0?'Əsas şəkil':`Şəkil ${index+1}`}</small>${index===0?'':`<form method="post" action="/admin/products/${product.id}/images/${image.id}/primary"><input type="hidden" name="csrf" value="${session.csrf}"><button type="submit" class="button small secondary">Əsas et</button></form>`}<form method="post" action="/admin/products/${product.id}/images/${image.id}/delete"><input type="hidden" name="csrf" value="${session.csrf}"><button type="submit" class="button small danger" aria-label="Şəkil ${index+1} sil">Şəkli sil</button></form></div>`).join('')}</div></section>`;
}

async function deleteProductImage(req,res,route,session){
  const body=await readBody(req);
  if(!validCsrf(body,session))return forbidden(res);
  const parts=route.split('/'),productId=Number(parts[3]),imageId=Number(parts[5]);
  const image=db.prepare('SELECT id,image_url FROM product_images WHERE id=? AND product_id=?').get(imageId,productId);
  if(!image)return notFound(res);
  db.exec('BEGIN');
  try{
    db.prepare('DELETE FROM product_images WHERE id=? AND product_id=?').run(imageId,productId);
    const first=db.prepare('SELECT image_url FROM product_images WHERE product_id=? ORDER BY position,id LIMIT 1').get(productId);
    db.prepare('UPDATE products SET image_url=?,updated_at=? WHERE id=?').run(first?.image_url||'',now(),productId);
    db.exec('COMMIT');
  }catch(error){db.exec('ROLLBACK');throw error;}
  // Shared image paths must remain available to other products.
  const shared=db.prepare('SELECT 1 FROM product_images WHERE image_url=? UNION ALL SELECT 1 FROM products WHERE image_url=? LIMIT 1').get(image.image_url,image.image_url);
  if(!shared){try{removeStoredImage(image.image_url)}catch(error){console.error('Unused image cleanup failed:',error.message)}}
  redirect(res,`/admin/products?edit=${productId}&image_deleted=1`);
}

async function setPrimaryProductImage(req,res,route,session){
  const body=await readBody(req);if(!validCsrf(body,session))return forbidden(res);
  const parts=route.split('/'),productId=Number(parts[3]),imageId=Number(parts[5]);
  const image=db.prepare('SELECT id,image_url FROM product_images WHERE id=? AND product_id=?').get(imageId,productId);
  if(!image)return notFound(res);
  db.exec('BEGIN');try{
    const others=db.prepare('SELECT id FROM product_images WHERE product_id=? AND id<>? ORDER BY position,id').all(productId,imageId);
    const update=db.prepare('UPDATE product_images SET position=? WHERE id=?');
    update.run(0,imageId);others.forEach((other,i)=>update.run(i+1,other.id));
    db.prepare('UPDATE products SET image_url=?,updated_at=? WHERE id=?').run(image.image_url,now(),productId);
    db.exec('COMMIT');
  }catch(error){db.exec('ROLLBACK');throw error;}
  redirect(res,`/admin/products?edit=${productId}&primary_saved=1`);
}



