mailService.start();
function mailSettingsPanel(session){
  const config=mailService.status();
  const labels={pending:'Növbədə',sending:'Göndərilir',submitted:'Gmail qəbul etdi',failed:'Göndərilmədi',skipped:'E-poçt yoxdur'};
  const errors={EAUTH:'Gmail tətbiq şifrəsini yoxlayın.',ECONNECTION:'Bağlantı alınmadı.',ETIMEDOUT:'Bağlantı vaxtı bitdi.',ESOCKET:'Təhlükəsiz bağlantı alınmadı.',EENVELOPE:'Alıcı qəbul edilmədi.',EMESSAGE:'Mesaj qəbul edilmədi.',SEND_FAILED:'Göndərmə xətası.',missing_email:'Sifarişdə düzgün e-poçt ünvanı yoxdur.'};
  const entries=mailService.recent().map(item=>`<li><strong>#${item.order_id}</strong> — ${escapeHtml(item.recipient||'—')}<br><small>${labels[item.state]||escapeHtml(item.state)} · Cəhd: ${item.attempts}${item.last_error?' · '+escapeHtml(errors[item.last_error]||'Göndərmə xətası.'):''}</small></li>`).join('');
  return `<section class="card notifications" style="margin-top:20px"><h2>E-poçt bildirişləri</h2><p>${config.configured?'Gmail göndərişi aktivdir.':config.enabled?'Gmail bağlantı məlumatları tamamlanmayıb.':'E-poçt göndərişi deaktivdir.'}</p><p>Göndərən: ${escapeHtml(config.sender||'Təyin edilməyib')}</p><p class="muted">Bildirişlər sifarişdəki e-poçt ünvanına göndərilir. Uğursuz göndərişlər 5 dəfəyədək yoxlanılır. Gmail-in qəbul etməsi gələnlər qutusuna çatdırılmanı təsdiqləmir.</p><ul class="notification-list">${entries||'<li>Hələ e-poçt bildirişi yoxdur.</li>'}</ul><form method="post" action="/admin/notifications/retry"><input type="hidden" name="csrf" value="${session.csrf}"><button class="button secondary">Uğursuz göndərişləri yenidən sına</button></form></section>`;
}


